  liveTag:      { display:'flex', alignItems:'center', gap:6 },
  liveDot:      { width:6, height:6, borderRadius:'50%', background:'#2ed573', boxShadow:'0 0 6px #2ed573' },
  liveTime:     { fontSize:11, fontFamily:'monospace', color:'#2ed573' },
  mesuresGrid:  { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:10 },
  mesureCard:   { background:'rgba(255,255,255,0.02)', border:'1px solid', borderRadius:8, overflow:'hidden' },
  mesureTop:    { padding:'10px 12px', display:'flex', alignItems:'center', gap:8 },
  mesureIconWrap:{ width:28, height:28, borderRadius:6, background:'rgba(255,255,255,0.05)', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 },
  mesureType:   { fontSize:11, fontWeight:600, color:'#e8eaf0', textTransform:'capitalize' },
  mesureMachine:{ fontSize:10, color:'#7a8394', fontFamily:'monospace', marginTop:1 },
  mesureBottom: { padding:'8px 12px 6px', display:'flex', alignItems:'baseline', gap:4 },
